<template><div><PageHeader title="Assessments" description="Create evaluations, record results and monitor learner performance."><template #actions><button class="btn primary" @click="open=true">+ Create assessment</button></template></PageHeader><div class="card"><DataTable :headers="['Assessment','Course','Batch','Participants','Average','Status','']" :actions="true"><tr v-for="item in items" :key="item.id"><td><strong>{{item.name}}</strong><div class="section-note">{{item.type}}</div></td><td>{{item.course}}</td><td>{{item.batch}}</td><td>{{item.participants}}</td><td>{{item.average}}%</td><td><StatusBadge :status="item.status"/></td><td><button class="btn secondary small">Results</button></td></tr></DataTable></div><Modal :open="open" title="Create assessment" description="Define a new evaluation for a course batch" @close="open=false"><form class="auth-form" @submit.prevent="save"><div class="field"><label>Assessment title</label><input class="input" v-model="form.name"></div><div class="form-grid"><div class="field"><label>Course</label><select class="select"><option>Laravel Fundamentals</option><option>Application Security</option></select></div><div class="field"><label>Type</label><select class="select"><option>Final assessment</option><option>Quiz</option><option>Assignment</option></select></div></div><div class="form-grid"><div class="field"><label>Maximum score</label><input class="input" value="100"></div><div class="field"><label>Pass percentage</label><input class="input" value="60"></div></div><button class="btn primary">Create assessment</button></form></Modal></div></template>
<script setup lang="ts">import {reactive,ref} from 'vue';import PageHeader from '../components/PageHeader.vue';import DataTable from '../components/DataTable.vue';import StatusBadge from '../components/StatusBadge.vue';import Modal from '../components/Modal.vue';import {useToast} from '../composables/useToast';const open=ref(false);const form=reactive({name:'Final Assessment'});const {push}=useToast();const items=[{id:1,name:'Laravel Fundamentals — Final',type:'Final assessment',course:'Laravel Fundamentals',batch:'2026-09-A',participants:30,average:82,status:'completed'},{id:2,name:'API Security Quiz',type:'Quiz',course:'Application Security',batch:'2026-09-C',participants:28,average:89,status:'active'},{id:3,name:'Deployment Assignment',type:'Assignment',course:'DevSecOps Essentials',batch:'2026-09-D',participants:18,average:76,status:'pending'}];function save(){open.value=false;push('Assessment created successfully.')}</script>
